import java.util.Map;

public class Config {
    public static String get(Map<String, String> settings, String key, String fallback) {
        if (settings == null) {
            return fallback;
        }
        String v = settings.get(key);
        return v == null ? fallback : v;
    }

    public static int getInt(Map<String, String> settings, String key, int fallback) {
        String v = get(settings, key, null);
        return v == null ? fallback : Integer.parseInt(v);
    }
}

